import Vue from 'vue'
import VueRouter from 'vue-router'
import store from '@/store'

Vue.use(VueRouter)

const routes = [
  { path: '/login', name: 'Login', component: () => import('@/views/Login.vue'), meta: { guest: true } },
  { path: '/register', name: 'Register', component: () => import('@/views/Register.vue'), meta: { guest: true } },
  {
    path: '/',
    component: () => import('@/views/Layout.vue'),
    meta: { requiresAuth: true },
    redirect: () => {
      const role = store.state.user.role
      if (role === 'admin') return '/admin'
      if (role === 'entrepreneur') return '/entrepreneur'
      if (role === 'investor') return '/investor'
      if (role === 'provider') return '/provider'
      return '/home'
    },
    children: [
      { path: 'home', name: 'Home', component: () => import('@/views/Home.vue') },
      { path: 'admin', name: 'Admin', component: () => import('@/views/admin/Dashboard.vue'), meta: { role: 'admin' } },
      { path: 'entrepreneur', name: 'Entrepreneur', component: () => import('@/views/entrepreneur/Dashboard.vue'), meta: { role: 'entrepreneur' } },
      { path: 'investor', name: 'Investor', component: () => import('@/views/investor/Dashboard.vue'), meta: { role: 'investor' } },
      { path: 'provider', name: 'Provider', component: () => import('@/views/provider/Dashboard.vue'), meta: { role: 'provider' } },
      { path: 'profile', name: 'Profile', component: () => import('@/views/Profile.vue') },
      { path: 'projects', name: 'ProjectList', component: () => import('@/views/project/List.vue') },
      { path: 'project/:id', name: 'ProjectDetail', component: () => import('@/views/project/Detail.vue') },
      { path: 'project-publish', name: 'ProjectPublish', component: () => import('@/views/project/Publish.vue'), meta: { role: 'entrepreneur' } },
      { path: 'my-projects', name: 'MyProjects', component: () => import('@/views/project/MyList.vue') },
      { path: 'services', name: 'ServiceList', component: () => import('@/views/resource/List.vue') },
      { path: 'service/:id', name: 'ServiceDetail', component: () => import('@/views/resource/Detail.vue') },
      { path: 'service-publish', name: 'ServicePublish', component: () => import('@/views/resource/Publish.vue'), meta: { role: ['provider', 'entrepreneur'] } },
      { path: 'my-services', name: 'MyServices', component: () => import('@/views/resource/MyList.vue'), meta: { role: ['provider', 'entrepreneur'] } },
      { path: 'my-investments', name: 'MyInvestments', component: () => import('@/views/investment/MyList.vue'), meta: { role: 'investor' } },
      { path: 'my-orders', name: 'MyOrders', component: () => import('@/views/order/MyList.vue') },
      { path: 'provider-orders', name: 'ProviderOrders', component: () => import('@/views/order/ProviderList.vue'), meta: { role: 'provider' } },
      { path: 'messages', name: 'Messages', component: () => import('@/views/Messages.vue') },
      { path: 'admin-users', name: 'AdminUsers', component: () => import('@/views/admin/UserList.vue'), meta: { role: 'admin' } },
      { path: 'admin-audit', name: 'AdminAudit', component: () => import('@/views/admin/Audit.vue'), meta: { role: 'admin' } },
      { path: 'admin-stats', name: 'AdminStats', component: () => import('@/views/admin/Stats.vue'), meta: { role: 'admin' } },
      { path: 'admin-config', name: 'AdminConfig', component: () => import('@/views/admin/Config.vue'), meta: { role: 'admin' } },
      { path: 'admin-log', name: 'AdminLog', component: () => import('@/views/admin/LogList.vue'), meta: { role: 'admin' } },
      { path: 'admin-roles', name: 'AdminRoles', component: () => import('@/views/admin/RoleManage.vue'), meta: { role: 'admin' } },
      { path: 'admin-backup', name: 'AdminBackup', component: () => import('@/views/admin/Backup.vue'), meta: { role: 'admin' } },
      { path: 'admin-projects', name: 'AdminProject', component: () => import('@/views/admin/ProjectManage.vue'), meta: { role: 'admin' } },
      { path: 'admin-services', name: 'AdminService', component: () => import('@/views/admin/ServiceManage.vue'), meta: { role: 'admin' } }
    ]
  }
]

const router = new VueRouter({ mode: 'history', base: process.env.BASE_URL, routes })

router.beforeEach((to, from, next) => {
  const token = store.state.user.token
  if (token && !store.state.user.role) {
    try {
      const saved = localStorage.getItem('user')
      if (saved) {
        const data = JSON.parse(saved)
        store.commit('user/SET_USER', {
          userId: data.userId,
          username: data.username,
          role: data.role,
          avatar: data.avatar,
          realName: data.realName,
          permissions: data.permissions || []
        })
      }
    } catch (_) {}
  }
  if (to.meta.guest && token) {
    return next('/')
  }
  if (to.meta.requiresAuth && !token) {
    return next('/login')
  }
  if (to.meta.role && store.state.user.role !== 'admin') {
    const roles = Array.isArray(to.meta.role) ? to.meta.role : [to.meta.role]
    if (!roles.includes(store.state.user.role)) {
      return next('/')
    }
  }
  next()
})

export default router
